#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<string> board(3);
    int countX = 0, countO = 0;

    for (string& row : board) {
        cin >> row;
        for (char cell : row) {
            countX += (cell == 'X');
            countO += (cell == '0');
        }
    }

    auto wins = [&](char player) {
        for (int i = 0; i < 3; ++i) {
            if (board[i][0] == player && board[i][1] == player &&
                board[i][2] == player)
                return true;

            if (board[0][i] == player && board[1][i] == player &&
                board[2][i] == player)
                return true;
        }

        return (board[0][0] == player && board[1][1] == player &&
                board[2][2] == player) ||
               (board[0][2] == player && board[1][1] == player &&
                board[2][0] == player);
    };

    bool winX = wins('X');
    bool winO = wins('0');

    if (countO > countX || countX - countO > 1 || (winX && winO) ||
        (winX && countX != countO + 1) ||
        (winO && countX != countO)) {
        cout << "illegal";
    } else if (winX) {
        cout << "the first player won";
    } else if (winO) {
        cout << "the second player won";
    } else if (countX + countO == 9) {
        cout << "draw";
    } else if (countX == countO) {
        cout << "first";
    } else {
        cout << "second";
    }

    return 0;
}

